Object.assign(SNIP,{"l45lr": "int x = 5;            // x là lvalue: có tên, có địa chỉ, còn dùng tiếp được\nx + 1;                // rvalue: giá trị tạm, dùng xong là mất\nstring s = \"ab\";\nstring t = s;         // s là lvalue: phải CHÉP (s còn dùng sau đó)\nstring u = s + \"c\";   // s + \"c\" là rvalue: CHUYỂN được (không ai dùng nó nữa)\nstring v = move(s);   // move(s): \"coi s như giá trị tạm\", v lấy ruột của s, s còn lại rỗng", "l45five": "class MangDong {\n    int* p; int n;\npublic:\n    MangDong(const MangDong& o);              // 1. hàm tạo sao chép\n    MangDong& operator=(const MangDong& o);   // 2. gán chép\n    MangDong(MangDong&& o) noexcept           // 3. hàm tạo chuyển: lấy ruột của o\n        : p(o.p), n(o.n) { o.p = nullptr; o.n = 0; }\n    MangDong& operator=(MangDong&& o) noexcept;   // 4. gán chuyển\n    ~MangDong();                              // 5. hàm hủy\n};"});PRESET_NOTES["l45"]={"Ví dụ: chép và chuyển một string": "b = a chép (a vẫn còn nguyên). c = move(a) lấy luôn dữ liệu của a, a còn lại rỗng. Tương tự, push_back(w) chép w vào vector, còn push_back(move(w)) chuyển w vào và w thành rỗng.", "Ví dụ: hàm tạo chuyển lấy ruột mảng": "b = a gọi hàm tạo sao chép: heap có thêm khối thứ hai. c = move(a) gọi hàm tạo chuyển: c trỏ vào chính khối của a, a.p thành nullptr và a.n = 0. Cuối main, a bị hủy nhưng không trả gì (delete[] nullptr), nên không có giải phóng hai lần.", "Ví dụ: gán chép và gán chuyển": "a = b: b là biến nên gọi gán chép. a = MangDong(7): vế phải là đối tượng tạm nên gọi gán chuyển (đối tượng tạm bị hủy ngay sau dòng đó, không giữ gì). a = move(b): gán chuyển, b còn lại rỗng (size 0).", "Ví dụ: const T& hay T&&": "Có cả hai bản: biến (ten) đi vào bản const string&; giá trị tạm (\"Binh\" đổi thành string tạm, ten + \" Chi\") và move(ten) đi vào bản string&&. Bản && biết đối số sắp bị bỏ nên được phép lấy ruột của nó.", "Ví dụ: trả về từ hàm không chép": "Chỉ có một dòng “tao 3” và một dòng “huy 3”: m được dựng thẳng vào chỗ của a (NRVO), không chép, cũng không chuyển. Vì vậy trả về vector, string, đối tượng lớn từ hàm là bình thường trong C++ hiện đại.", "Ví dụ: chuyển thành viên string": "Trong hàm tạo chuyển, o là một biến có tên nên o.s là lvalue: phải viết move(o.s) thì string mới được chuyển (bỏ move thì s(o.s) lại chép). Sau đó a.s rỗng.", "Bẫy: dùng biến sau khi đã move": "Sau move, a còn hợp lệ nhưng đã rỗng (với vector của libstdc++). Đọc a[0] lúc này là lỗi. Muốn dùng lại thì gán hoặc thêm giá trị mới như ở dòng push_back.", "Lỗi: truyền biến vào tham số T&&": "a là lvalue (có tên, còn dùng tiếp) nên không gắn vào string&& được. Nếu thật sự muốn giao a cho hàm: lay(move(a)); nếu hàm chỉ đọc: đổi tham số thành const string&.", "Lỗi: lớp chỉ chuyển được": "Lớp có hàm tạo chuyển tự viết thì C++ không tự tạo hàm tạo sao chép (hàm đó bị xóa), giống unique_ptr. ChiChuyen b = move(a); thì được."};EX_HINTS["l45"]=[["Hàm tạo chuyển: lấy con trỏ o.p và o.n, rồi đặt o.p = nullptr, o.n = 0.", "Gán chuyển: kiểm tra this != &o, delete[] mảng cũ, lấy mảng của o, đặt o rỗng, return *this."], ["tam lấy ruột của a; a lấy ruột của b; b lấy ruột của tam.", "Đây cũng chính là cách std::swap làm việc."], ["push_back(move(w)) chuyển dữ liệu của w vào vector; w rỗng và được cin >> w ghi giá trị mới ở vòng sau.", "Chỉ dùng w sau khi đã gán giá trị mới (cin >> w) là an toàn."]];
/* ===================== BÀI 45 · Move semantics ===================== */
/* Bài 45 · Move semantics
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P45=[{label:"Ví dụ: chép và chuyển một string",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\n#include <utility>\nusing namespace std;\n\nint main() {\n    string a = \"mot chuoi rat dai\";\n    string b = a;\n    string c = move(a);\n    cout << \"a = [\" << a << \"]\\n\";\n    cout << \"b = [\" << b << \"], c = [\" << c << \"]\\n\";\n    vector<string> v;\n    string w = \"tu\";\n    v.push_back(w);\n    v.push_back(move(w));\n    cout << v.size() << \" phan tu, w = [\" << w << \"]\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: hàm tạo chuyển lấy ruột mảng",input:"",code:"#include <iostream>\n#include <utility>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : p(new int[n]), n(n) {\n        for (int i = 0; i < n; i++) p[i] = i;\n        cout << \"tao \" << n << \"\\n\";\n    }\n    MangDong(const MangDong& o) : p(new int[o.n]), n(o.n) {\n        for (int i = 0; i < n; i++) p[i] = o.p[i];\n        cout << \"chep \" << n << \"\\n\";\n    }\n    MangDong(MangDong&& o) noexcept : p(o.p), n(o.n) {\n        o.p = nullptr;\n        o.n = 0;\n        cout << \"chuyen \" << n << \"\\n\";\n    }\n    ~MangDong() {\n        delete[] p;\n        cout << \"huy \" << n << \"\\n\";\n    }\n    int size() const { return n; }\n};\nint main() {\n    MangDong a(4);\n    MangDong b = a;\n    MangDong c = move(a);\n    cout << a.size() << \" \" << b.size() << \" \" << c.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: gán chép và gán chuyển",input:"",code:"#include <iostream>\n#include <utility>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : p(new int[n]), n(n) {}\n    MangDong(const MangDong& o) : p(new int[o.n]), n(o.n) {\n        for (int i = 0; i < n; i++) p[i] = o.p[i];\n    }\n    MangDong& operator=(const MangDong& o) {\n        if (this != &o) {\n            delete[] p;\n            n = o.n;\n            p = new int[n];\n            for (int i = 0; i < n; i++) p[i] = o.p[i];\n        }\n        cout << \"gan chep\\n\";\n        return *this;\n    }\n    MangDong& operator=(MangDong&& o) noexcept {\n        if (this != &o) {\n            delete[] p;\n            p = o.p;\n            n = o.n;\n            o.p = nullptr;\n            o.n = 0;\n        }\n        cout << \"gan chuyen\\n\";\n        return *this;\n    }\n    ~MangDong() { delete[] p; }\n    int size() const { return n; }\n};\nint main() {\n    MangDong a(3), b(5);\n    a = b;\n    a = MangDong(7);\n    a = move(b);\n    cout << a.size() << \" \" << b.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: const T& hay T&&",input:"",code:"#include <iostream>\n#include <string>\n#include <utility>\nusing namespace std;\n\nvoid xem(const string& s) {\n    cout << \"doc nho: \" << s << \"\\n\";\n}\nvoid xem(string&& s) {\n    cout << \"gia tri tam: \" << s << \"\\n\";\n}\nint main() {\n    string ten = \"An\";\n    xem(ten);\n    xem(\"Binh\");\n    xem(ten + \" Chi\");\n    xem(move(ten));\n    return 0;\n}"},{label:"Ví dụ: trả về từ hàm không chép",input:"",code:"#include <iostream>\n#include <utility>\nusing namespace std;\n\nclass MangDong {\n    int* p;\n    int n;\npublic:\n    MangDong(int n) : p(new int[n]), n(n) {\n        for (int i = 0; i < n; i++) p[i] = i;\n        cout << \"tao \" << n << \"\\n\";\n    }\n    MangDong(const MangDong& o) : p(new int[o.n]), n(o.n) {\n        for (int i = 0; i < n; i++) p[i] = o.p[i];\n        cout << \"chep \" << n << \"\\n\";\n    }\n    MangDong(MangDong&& o) noexcept : p(o.p), n(o.n) {\n        o.p = nullptr;\n        o.n = 0;\n        cout << \"chuyen \" << n << \"\\n\";\n    }\n    ~MangDong() {\n        delete[] p;\n        cout << \"huy \" << n << \"\\n\";\n    }\n    int size() const { return n; }\n};\nMangDong taoMang(int n) {\n    MangDong m(n);\n    return m;\n}\nint main() {\n    MangDong a = taoMang(3);\n    cout << \"a co \" << a.size() << \" phan tu\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Ví dụ: chuyển thành viên string",input:"",code:"#include <iostream>\n#include <string>\n#include <utility>\nusing namespace std;\n\nclass Hop {\n    string s;\npublic:\n    Hop(string x) : s(x) {}\n    Hop(const Hop& o) : s(o.s) { cout << \"chep\\n\"; }\n    Hop(Hop&& o) noexcept : s(move(o.s)) { cout << \"chuyen\\n\"; }\n    string lay() const { return s; }\n};\nint main() {\n    Hop a(\"abc\");\n    Hop b(move(a));\n    cout << \"[\" << a.lay() << \"] [\" << b.lay() << \"]\\n\";\n    return 0;\n}"},{label:"Bẫy: dùng biến sau khi đã move",input:"",code:"#include <iostream>\n#include <string>\n#include <vector>\n#include <utility>\nusing namespace std;\n\nint main() {\n    vector<int> a = {1, 2, 3};\n    vector<int> b = move(a);\n    cout << \"a con \" << a.size() << \" phan tu\\n\";\n    a.push_back(9);\n    cout << \"Gan lai thi dung tiep duoc: \" << a[0] << \"\\n\";\n    return 0;\n}",viz:[{type:"mem"}]},{label:"Lỗi: truyền biến vào tham số T&&",input:"",code:"#include <iostream>\n#include <string>\nusing namespace std;\n\nvoid lay(string&& s) {\n    cout << s << \"\\n\";\n}\nint main() {\n    string a = \"x\";\n    lay(a);\n    return 0;\n}"},{label:"Lỗi: lớp chỉ chuyển được",input:"",code:"#include <iostream>\n#include <utility>\nusing namespace std;\n\nclass ChiChuyen {\n    int* p;\npublic:\n    ChiChuyen() : p(new int(1)) {}\n    ChiChuyen(ChiChuyen&& o) noexcept : p(o.p) { o.p = nullptr; }\n    ~ChiChuyen() { delete p; }\n};\nint main() {\n    ChiChuyen a;\n    ChiChuyen b = a;\n    return 0;\n}"}];
const sim45=makeSim2(document.getElementById("sim-l45"),{id:"s45",presets:P45});
makeEx2(document.getElementById("ex-l45"),sim45,[{t:"Hàm tạo chuyển và gán chuyển",d:"Lớp <code>Anh<\/code> giữ một mảng trên heap, đã có hàm tạo sao chép và gán chép (in <code>chep<\/code>, <code>gan chep<\/code>). Hãy thêm hàm tạo chuyển (in <code>chuyen<\/code>) và toán tử gán chuyển (in <code>gan chuyen<\/code>) để hàm main không còn chép mảng nào. Đối tượng bị chuyển phải còn <code>size() == 0<\/code>.",tests:[{in:"3\n1 2 3",out:"chuyen\ngan chuyen\n0 0 3 6"},{in:"1\n-5",out:"chuyen\ngan chuyen\n0 0 1 -5"},{in:"4\n10 20 30 40",out:"chuyen\ngan chuyen\n0 0 4 100"}],start:"#include <iostream>\n#include <utility>\nusing namespace std;\n\nclass Anh {\n    int* p;\n    int n;\npublic:\n    Anh(int n) : p(new int[n]), n(n) {}\n    Anh(const Anh& o) : p(new int[o.n]), n(o.n) {\n        for (int i = 0; i < n; i++) p[i] = o.p[i];\n        cout << \"chep\\n\";\n    }\n    Anh& operator=(const Anh& o) {\n        if (this != &o) {\n            delete[] p;\n            n = o.n;\n            p = new int[n];\n            for (int i = 0; i < n; i++) p[i] = o.p[i];\n        }\n        cout << \"gan chep\\n\";\n        return *this;\n    }\n    // Anh(Anh&& o) noexcept ...\n    // Anh& operator=(Anh&& o) noexcept ...\n    ~Anh() { delete[] p; }\n    void dat(int i, int x) { p[i] = x; }\n    int size() const { return n; }\n    long long tong() const {\n        long long t = 0;\n        for (int i = 0; i < n; i++) t += p[i];\n        return t;\n    }\n};\nint main() {\n    int n;\n    cin >> n;\n    Anh a(n);\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        a.dat(i, x);\n    }\n    Anh b = move(a);\n    Anh c(1);\n    c = move(b);\n    cout << a.size() << \" \" << b.size() << \" \" << c.size() << \" \" << c.tong() << \"\\n\";\n    return 0;\n}",need:/Anh\s*\(\s*Anh\s*&&[\s\S]*operator\s*=\s*\(\s*Anh\s*&&/,needMsg:"Hãy viết Anh(Anh&& o) và operator=(Anh&& o)."},{t:"Đổi chỗ hai chuỗi bằng move",d:"Viết hàm <code>void doiCho(string&amp; a, string&amp; b)<\/code> đổi giá trị hai chuỗi bằng ba lần chuyển (dùng một biến tạm và <code>move<\/code>), không chép chuỗi nào. Chương trình đọc q cặp chuỗi, đổi chỗ rồi in mỗi cặp trên một dòng.",tests:[{in:"2\nan binh\nx yy",out:"binh an\nyy x"},{in:"1\nabc abc",out:"abc abc"}],start:"#include <iostream>\n#include <string>\n#include <utility>\nusing namespace std;\n\nvoid doiCho(string& a, string& b) {\n    // string tam = move(a); ...\n}\nint main() {\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        string a, b;\n        cin >> a >> b;\n        doiCho(a, b);\n        cout << a << \" \" << b << \"\\n\";\n    }\n    return 0;\n}",need:/move\s*\([\s\S]*move\s*\([\s\S]*move\s*\(/,needMsg:"Hãy dùng move ba lần trong doiCho."},{t:"Gom từ vào danh sách",d:"Nhập n rồi n từ. Mỗi từ được đọc vào một biến <code>string w<\/code>, rồi chuyển vào <code>vector&lt;string&gt;<\/code> bằng <code>push_back(move(w))<\/code> (không chép). In các từ theo thứ tự ngược trên một dòng, dòng sau in tổng số ký tự, dòng cuối in <code>w rong<\/code> nếu w (biến đọc từ cuối cùng) đã rỗng sau khi chuyển.",tests:[{in:"3\nmot hai ba",out:"ba hai mot\n8\nw rong"},{in:"1\nx",out:"x\n1\nw rong"}],start:"#include <iostream>\n#include <string>\n#include <vector>\n#include <utility>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> v;\n    string w;\n    for (int i = 0; i < n; i++) {\n        cin >> w;\n        // v.push_back(...);\n    }\n    // in ngược, tổng số ký tự\n    if (w.empty()) cout << \"w rong\\n\";\n    return 0;\n}",need:/push_back\s*\(\s*move\s*\(\s*w\s*\)\s*\)/,needMsg:"Hãy chuyển bằng v.push_back(move(w))."}]);

makeQuiz("quiz45","score45",[{"q": "Biểu thức nào là rvalue?", "o": ["x", "a[i]", "x + 1", "o.ten"], "a": 2, "e": "x + 1 là giá trị tạm, không có tên; ba biểu thức kia đều có tên (lvalue)."}, {"q": "<code>string b = move(a);<\/code> Sau dòng này, với libstdc++, a là:", "o": ["Vẫn như cũ", "Chuỗi rỗng (hợp lệ, gán lại được)", "Đã bị hủy, dùng là lỗi biên dịch", "nullptr"], "a": 1, "e": "Đối tượng bị chuyển vẫn hợp lệ; string bị chuyển thường rỗng. Đừng đọc giá trị của nó trước khi gán mới."}, {"q": "Vì sao hàm tạo chuyển của MangDong phải đặt <code>o.p = nullptr<\/code>?", "o": ["Để tiết kiệm bộ nhớ", "Để hàm hủy của o không delete[] vùng nhớ mà đối tượng mới vừa lấy", "Vì C++ bắt buộc", "Để o không dùng được nữa"], "a": 1, "e": "Không đặt nullptr thì hai đối tượng cùng giữ một vùng nhớ và nó bị giải phóng hai lần."}, {"q": "Có <code>f(const string&amp;)<\/code> và <code>f(string&amp;&amp;)<\/code>. Lời gọi <code>f(s + \"!\")<\/code> chọn bản nào?", "o": ["const string&", "string&&", "Lỗi mơ hồ", "Không gọi được"], "a": 1, "e": "s + \"!\" là giá trị tạm, ưu tiên bản nhận tham chiếu rvalue."}]);

